CREATE FUNCTION truss.runtime_catalog_only_business_refusal_candidate() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path TO pg_catalog, pg_temp AS $$
BEGIN
 IF TG_LEVEL<>'STATEMENT' OR TG_WHEN<>'BEFORE' OR TG_TABLE_SCHEMA<>'truss'
  OR TG_NAME<>'a_truss_catalog_only_business_refusal' OR TG_NARGS<>0
  OR TG_OP NOT IN ('INSERT','UPDATE','DELETE','TRUNCATE')
  OR NOT TG_TABLE_NAME=ANY(ARRAY['object','edge','edge_limit','key_tombstone','record_source','feed_consumer','journal','row_home_journal_stage','row_home_state','row_home_node','row_home_scalar','row_home_touch','row_home_capacity','key_bucket_guard','object_key_bucket','object_key_reservation_bucket','complete_feed_consumer','complete_feed_administration_receipt','complete_feed_seed_attempt','complete_feed_seed_artifact','key_lifecycle_history','key_migration_receipt','request_receipt_route_guard','request_receipt','request_receipt_protection','schema_change']) THEN
  RAISE EXCEPTION 'unregistered catalog-only business event' USING ERRCODE='55000'; END IF;
 RAISE EXCEPTION 'business writes are outside selected catalog-only scope' USING ERRCODE='0A000';
END;
$$; REVOKE ALL ON FUNCTION truss.runtime_catalog_only_business_refusal_candidate() FROM public; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.object EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.object ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.edge EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.edge ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.edge_limit EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.edge_limit ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.key_tombstone EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.key_tombstone ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.record_source EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.record_source ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.feed_consumer EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.feed_consumer ENABLE ALWAYS TRIGGER a_truss_catalog_only_business_refusal; CREATE TRIGGER a_truss_catalog_only_business_refusal BEFORE INSERT OR DELETE OR UPDATE OR TRUNCATE ON truss.journal EXECUTE FUNCTION truss.runtime_catalog_only_business_refusal_candidate(); ALTER TABLE truss.